// md-preview: the Markdown files Claude edits, rendered like GitHub, in a pane.
//   A toast says when one changes; /md opens the pane on the latest one.
//   b shows the file before the last edit next to it now; /md compare <a> <b> shows
//   two files side by side; o opens the page in the browser.
//   GitHub renders it (gh api /markdown) when the file is in a GitHub repo and gh is
//   signed in; a small built-in renderer does otherwise. Headless Chrome draws the
//   page to PNG for the terminal; without Chrome or an image terminal, a text view.
//   A file Claude edits is drawn ahead, in the background, so /md opens on a page that
//   is already drawn; drawings are kept by what they show, so n/p back to a file is instant.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { MdFile, MdFrame, MdPair } from '../types'
import { changedChunks, parse, toHtml, toLines, withMarks } from './md'
import type { Line } from './md'
import { fileUrl, page } from './page'
import type { Side } from './page'

const PANE = 'md-preview'
// Chrome or a Chromium, first found; macOS first, then the usual Linux names.
export const CHROMES = [
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/Applications/Chromium.app/Contents/MacOS/Chromium',
  '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
  '/Applications/Brave Browser.app/Contents/MacOS/Brave Browser',
  '/usr/bin/google-chrome',
  '/usr/bin/google-chrome-stable',
  '/usr/bin/chromium',
  '/usr/bin/chromium-browser',
]
const GH_MAX_BYTES = 390_000 // GitHub's API takes up to about 400 KB
const BEFORE_MAX = 400_000 // longer earlier texts are not kept for b
const BEFORE_FILES = 5 // only the latest files keep their earlier text
export const MD_FILE = /\.(md|mdx|markdown)$/i
const EDIT_TOOLS = new Set(['Write', 'Edit', 'MultiEdit'])
const CELL_PX = 9 // page pixels per terminal column
const ROW_PX = 19 // page pixels per terminal row
const PART_ROWS = 250 // an Image is at most 255 rows: taller pages come in parts
const SIDE_BY_SIDE_COLUMNS = 120 // narrower panes stack a compare
const MAX_FILES = 30
const GH_TIMEOUT_MS = 10_000
const CACHE_SIZE = 20 // drawings kept, the least recently shown dropped first
const AHEAD_FILES = 5 // files waiting to be drawn ahead; older ones are dropped

// Draws page.html into part-N.png, PART_ROWS rows each; prints "<rows> <parts>".
// Headless Chrome writes its output but does not always exit: wait for the file, then
// close that Chrome (its own throwaway profile, never the person's browser).
// $1 chrome  $2 page URL  $3 out dir  $4 profile  $5 width (css px)  $6 scale
export const SCRIPT = `c="$1"; pg="$2"; out="$3"; prof="$4"; w="$5"; sc="$6"; pid=""
mkdir -p "$out"; rm -f "$out"/part-*.png "$out"/dom.html
stop() { sleep 0.2; pkill -P "$1" 2>/dev/null; kill "$1" 2>/dev/null; }
trap '[ -n "$pid" ] && { pkill -P $pid 2>/dev/null; kill $pid 2>/dev/null; }' EXIT INT TERM
"$c" --headless=new --disable-gpu --hide-scrollbars --no-first-run --no-default-browser-check --user-data-dir="$prof" --window-size="$w,800" --dump-dom "$pg" >"$out/dom.html" 2>/dev/null & pid=$!
i=0; while ! grep -q '</html>' "$out/dom.html" 2>/dev/null && [ $i -lt 100 ]; do sleep 0.1; i=$((i+1)); done; stop $pid
hgt=$(sed -n 's/.*data-height="\\([0-9]*\\)".*/\\1/p' "$out/dom.html" | head -1)
[ -n "$hgt" ] || exit 2
rows=$(( (hgt + ${ROW_PX - 1}) / ${ROW_PX} )); [ $rows -gt 1500 ] && rows=1500
n=0; at=0
while [ $at -lt $rows ]; do
  r=$((rows - at)); [ $r -gt ${PART_ROWS} ] && r=${PART_ROWS}
  f="$out/part-$n.png"
  "$c" --headless=new --disable-gpu --hide-scrollbars --no-first-run --no-default-browser-check --user-data-dir="$prof" --force-device-scale-factor="$sc" --window-size="$w,$((r * ${ROW_PX}))" --screenshot="$f" "$pg#$((at * ${ROW_PX}))" >/dev/null 2>&1 & pid=$!
  i=0; while [ ! -s "$f" ] && [ $i -lt 100 ]; do sleep 0.1; i=$((i+1)); done; stop $pid
  [ -s "$f" ] || exit 3
  n=$((n+1)); at=$((at + r))
done
echo "$rows $n"`

// Held by the host, so a hot reload keeps them.
const files = atom({ plugin: 'md-preview', key: 'files' } as const, [] as MdFile[])
const shown = atom({ plugin: 'md-preview', key: 'shown' } as const, null as string | null)
const pair = atom({ plugin: 'md-preview', key: 'pair' } as const, null as MdPair)
const compare = atom({ plugin: 'md-preview', key: 'compare' } as const, false)
const frame = atom({ plugin: 'md-preview', key: 'frame' } as const, null as MdFrame)
const view = atom({ plugin: 'md-preview', key: 'view' } as const, 'page' as 'page' | 'text')
const note = atom({ plugin: 'md-preview', key: 'note' } as const, '')

// The module's own bookkeeping; a reload starts it over.
const draw = { pending: false, dirty: false, n: 0, columns: 100, failed: '', drawing: '', opened: 0, force: false }
// One drawing, in its own folder (frame-<slot>), kept until it is the least recently shown.
type Drawn = { slot: number; columns: number; parts: { file: string; rows: number }[]; n: number; via: 'GitHub' | 'built-in' }
const cache = new Map<string, Drawn>() // by what it shows (see cacheKey); oldest first
const ahead = new Set<string>() // files to draw before /md asks for them; newest last
const repos = new Map<string, string | null>() // each folder's GitHub repo, from its remotes
const ghFailed = new Set<string>() // repos whose last GitHub render failed
const turn = { isOn: false } // the main turn is under way: draw ahead once it ends
const session = { cwd: '', home: '', command: 'md', canImage: false, chrome: '', noChrome: false, ghDownUntil: 0 }
const toasted = new Set<string>() // files toasted this turn
const turnBefore = new Map<string, string | null>() // each file's text before this turn's first edit
// Markdown files before the turn's first shell command, to catch writes that skip Write/Edit (`cat > README.md`).
const shot = { taken: false, isFull: false, listed: new Set<string>(), texts: new Map<string, string>(), tooBig: new Set<string>() }
const SNAPSHOT_FILES = 200
const SHELL_TOOLS = new Set(['Bash', 'PowerShell'])
let snapshotting: Promise<void> | null = null // shared, so parallel shell calls take one snapshot

const base = (path: string) => path.slice(path.lastIndexOf('/') + 1)
const folder = (path: string) => path.slice(0, path.lastIndexOf('/')) || '/'

// What the pane shows: one file, a file before and after its last edit, or two files.
type Part = { label?: string; path: string; isBefore?: boolean }
type Plan = { key: string; title: string; parts: Part[] }
type Loaded = { label?: string; path: string; text: string; marks: number[] }

// owner/repo from `git remote -v`, the first GitHub remote.
export function githubRepo(remotes: string): string | null {
  const m = remotes.match(/(?:^|\s)(?:[\w.-]+@github\.com:|(?:https?|ssh|git):\/\/(?:[^@\s/]+@)?github\.com\/)([\w.-]+)\/([\w.-]+?)(?:\.git)?\/?(?:\s|$)/m)
  return m ? `${m[1]}/${m[2]}` : null
}

// Terminals that draw pictures, and not through tmux (it passes none).
async function imageTerminal($: EngineInterface) {
  const low = (v: string | undefined) => (v ?? '').toLowerCase()
  if (low(await $.env.get('TMUX').catch(() => undefined))) return false
  const program = low(await $.env.get('TERM_PROGRAM').catch(() => undefined))
  const term = low(await $.env.get('TERM').catch(() => undefined))
  return /ghostty|iterm|wezterm|kitty/.test(program) || /kitty|ghostty|foot|wezterm/.test(term)
}

async function paneUp($: EngineInterface) {
  return (await $.ui.panes()).some(p => p.id === PANE && p.isPlaced)
}

function absolute(arg: string) {
  let p = arg.replace(/^["']|["']$/g, '')
  if (p.startsWith('~/') && session.home) p = session.home + p.slice(1)
  else if (!p.startsWith('/')) p = `${session.cwd.replace(/\/$/, '')}/${p}`
  const parts: string[] = []
  for (const s of p.split('/')) {
    if (s === '..') parts.pop()
    else if (s && s !== '.') parts.push(s)
  }
  return `/${parts.join('/')}`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    session.cwd = e.cwd
    session.home = (await $.env.get('HOME').catch(() => undefined)) ?? ''
    session.canImage = await imageTerminal($)
    // /md, or /mdview if a built-in ever takes /md.
    for (const name of ['md', 'mdview']) {
      const ok = await $.command
        .register({ name, description: 'Preview the Markdown files Claude edited, rendered like GitHub', argumentHint: '[path | compare <a> <b> | open]' })
        .then(() => true)
        .catch(() => false)
      if (ok) {
        session.command = name
        break
      }
    }
    return r
  })

  on('turn.start', async (_$, e, next) => {
    if (!e.agentId) {
      // A subagent starting mid-turn must not drop the main turn's tracking.
      toasted.clear()
      turnBefore.clear()
      resetSnapshot()
      turn.isOn = true
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId) return r
    if (shot.taken) await compareSnapshot($).catch(() => {}) // after next(e): the turn is already over
    turn.isOn = false
    await startAhead($).catch(() => {}) // the files the turn changed, each drawn once, as it left them
    return r
  })

  // Reads what the main agent wrote; never blocks or changes the call.
  on('tool.call', async ($, e, next) => {
    // Shell commands can write Markdown without Write/Edit: snapshot before the turn's first one,
    // compare at turn end. Turns without a shell command cost nothing.
    if (SHELL_TOOLS.has(e.tool) && !shot.taken) {
      snapshotting ??= takeSnapshot($).catch(() => {}).finally(() => (snapshotting = null))
      await snapshotting
    }
    if (!EDIT_TOOLS.has(e.tool) || e.agentId) return next(e)
    const path = (e as unknown as { file_path?: unknown }).file_path
    if (typeof path !== 'string' || !MD_FILE.test(path)) return next(e)
    const before = await $.fs.read(path).catch(() => null) // before the write lands
    const r = await next(e)
    if (r.deny !== undefined || r.isError === true) return r
    await changed($, path, typeof before === 'string' ? before : null).catch(() => {}) // quick: a read and a toast
    return r
  })

  on('command.run', { command: 'md' }, async ($, e) => command($, e.args))
  on('command.run', { command: 'mdview' }, async ($, e) => command($, e.args))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const list = await read($, files)
    const path = await read($, shown)
    const two = await read($, pair)
    const isCompare = await read($, compare)
    const v = await read($, view)
    const msg = await read($, note)
    const columns = Math.max(20, e.props.bodyColumns)
    draw.columns = columns
    const p = await plan($)
    const i = list.findIndex(f => f.path === path)
    const isPage = e.surface === 'terminal' && v === 'page' && session.canImage && !session.noChrome
    const f = await read($, frame)
    const file = list.find(x => x.path === path)
    const where = two ? `${base(two.a)} | ${base(two.b)}` : path ? base(path) : ''
    const info = two
      ? '  side by side'
      : `  ${i + 1}/${list.length}${isCompare ? (file?.before !== undefined ? ' · before | after' : ' · new file, no earlier version') : ''}${file?.marks.length ? ' · green bar: changed in the last edit' : ''}`
    const head = (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Button key="prev" label="Prev" hotkey="p" onPress={() => step($, -1)} />
          <Button key="next" label="Next" hotkey="n" onPress={() => step($, 1)} />
          <Button key="before" label={isCompare ? 'Single' : 'Before'} hotkey="b" onPress={() => toggleCompare($)} />
          <Button key="again" label="Render" hotkey="r" onPress={() => again($)} />
          <Button key="view" label={v === 'page' ? 'Text' : 'Page'} hotkey="t" onPress={() => toggleView($)} />
          <Button key="open" label="Browser" hotkey="o" onPress={() => void openInBrowser($).then(t => $.ui.toast(`md-preview: ${t}`)).catch(() => {})} />
          <Button key="close" label="Close" hotkey="q" role="dismiss" onPress={() => $.ui.close({ id: PANE })} />
        </Box>
        {p && (
          <Text wrap="truncate-end">
            <Text bold>{where}</Text>
            <Text dimColor>{`${info}${isPage && f?.key === p.key ? ` · ${f.via}` : ''}`}</Text>
          </Text>
        )}
      </Box>
    )
    if (!p) {
      return (
        <Box flexDirection="column">
          {head}
          <Text dimColor>{`No Markdown edits yet. /${session.command} <path> opens a file.`}</Text>
        </Box>
      )
    }

    if (isPage) {
      const key = `${p.key}@${columns}`
      const isCurrent = f !== null && f.key === p.key && f.columns === columns
      if (!isCurrent && draw.failed !== key) {
        if (draw.pending) draw.dirty = true // draw again once this one is done
        else void renderSoon($).catch(() => {})
      }
      // The last drawing of the same view stays up while a newer one draws, scaled to the width.
      const same = f !== null && sameView(f.key, p.key)
      if (f && same) {
        const { Image } = $.ui.resolve(e)
        return (
          <Box flexDirection="column">
            {head}
            {f.parts.map((part, k) => (
              <Image key={`part-${k}`} source={{ file: part.file, format: 'png', generation: f.n }} columns={columns} rows={Math.max(1, Math.min(255, Math.round((part.rows * columns) / f.columns)))} alt={k === 0 ? `${where}, rendered` : ' '} />
            ))}
          </Box>
        )
      }
    }

    // The text view: while the page draws, and where it cannot.
    const sides = await load($, p)
    const many = sides.length > 1
    const lines: Line[] = []
    for (const s of sides) {
      if (many) lines.push({ prefix: '', segs: [{ text: `── ${s.label ?? base(s.path)} ──`, bold: true, color: 'yellow' }] }, { prefix: '', segs: [] })
      lines.push(...toLines(parse(withMarks(s.text, s.marks)), columns - 2))
      if (many) lines.push({ prefix: '', segs: [] })
    }
    const status = isPage ? msg || 'Rendering…' : msg
    return (
      <Box flexDirection="column">
        {head}
        {status && <Text dimColor>{status}</Text>}
        {sides.length === 0 && <Text color="red">{`Cannot read ${where}`}</Text>}
        {lines.slice(0, 3000).map((l, k) => (
          <Text key={`l${k}`} wrap="wrap">
            <Text color="green">{l.mark ? '▌' : ' '}</Text>
            <Text dimColor>{l.prefix}</Text>
            {l.segs.length === 0 ? <Text> </Text> : l.segs.map((s, j) => (
              <Text key={`s${j}`} bold={s.bold} italic={s.italic} dimColor={s.dim} color={s.color} underline={s.underline} strikethrough={s.strike}>
                {s.text.length > 4000 ? `${s.text.slice(0, 4000)}…` : s.text /* a Text child holds at most 10,000 characters */}
              </Text>
            ))}
          </Text>
        ))}
      </Box>
    )
  })
}

// Two keys name the same view when only the versions differ.
function sameView(a: string, b: string) {
  return a.replace(/\u0001\d+/g, '') === b.replace(/\u0001\d+/g, '')
}

// What to show now, without reading any file.
async function plan($: EngineInterface): Promise<Plan | null> {
  return planFor(await read($, files), await read($, shown), await read($, pair), await read($, compare))
}

function planFor(list: MdFile[], path: string | null, two: MdPair, isCompare: boolean): Plan | null {
  const at = (p: string) => list.find(f => f.path === p)?.at ?? 0
  if (two) return { key: `pair:${two.a}\u0001${at(two.a)}|${two.b}\u0001${at(two.b)}`, title: `${base(two.a)} | ${base(two.b)}`, parts: [{ label: base(two.a), path: two.a }, { label: base(two.b), path: two.b }] }
  if (!path) return null
  const file = list.find(f => f.path === path)
  if (isCompare && file?.before !== undefined) {
    return { key: `cmp:${path}\u0001${at(path)}`, title: `${base(path)}: before | after`, parts: [{ label: 'Before', path, isBefore: true }, { label: 'After', path }] }
  }
  return { key: `one:${path}\u0001${at(path)}`, title: base(path), parts: [{ path }] }
}

// The texts a plan shows, with the blocks to mark green.
async function load($: EngineInterface, p: Plan): Promise<Loaded[]> {
  const list = await read($, files)
  const out: Loaded[] = []
  for (const part of p.parts) {
    const file = list.find(f => f.path === part.path)
    const text = part.isBefore ? file?.before : await $.fs.read(part.path).catch(() => null)
    if (typeof text !== 'string') return []
    out.push({ label: part.label, path: part.path, text, marks: part.isBefore ? [] : (file?.marks ?? []) })
  }
  // Two files: mark what the second has that the first does not.
  if (p.key.startsWith('pair:') && out.length === 2) {
    const [a, b] = out as [Loaded, Loaded]
    b.marks = changedChunks(a.text, b.text)
    a.marks = []
  }
  return out
}

// /md, /md <path>, /md compare <a> <b>, /md open.
async function command($: EngineInterface, args: string) {
  const words = args.trim().split(/\s+/).filter(Boolean)
  if (words[0] === 'open') return { text: await openInBrowser($) }
  if (words[0] === 'compare') {
    if (words.length !== 3) return { text: `usage: /${session.command} compare <fileA> <fileB>` }
    const [a, b] = [absolute(words[1] as string), absolute(words[2] as string)]
    for (const f of [a, b]) {
      if (!MD_FILE.test(f)) return { text: `${base(f)} is not a .md, .mdx or .markdown file.` }
      if (!(await $.fs.exists(f).catch(() => false))) return { text: `no file at ${f}` }
    }
    await update($, pair, () => ({ a, b }))
    await update($, files, list => list.map(f => (f.path === a || f.path === b ? { ...f, at: Date.now() } : f)))
    await fromCache($).catch(() => false) // already drawn: the pane opens on the page
    await $.ui.open({ id: PANE, title: 'Markdown', focus: true })
    void renderSoon($).catch(() => {})
    return { text: `${base(a)} | ${base(b)} side by side. o: open in the browser · q: close` }
  }
  let target: string | null = null
  if (words.length) {
    const abs = absolute(args.trim())
    if (!MD_FILE.test(abs)) return { text: 'give a .md, .mdx or .markdown file.' }
    if (!(await $.fs.exists(abs).catch(() => false))) return { text: `no file at ${abs}` }
    await update($, files, list => (list.some(f => f.path === abs) ? list : [{ path: abs, at: Date.now(), marks: [] }, ...list].slice(0, MAX_FILES)))
    target = abs
  } else {
    target = (await read($, files))[0]?.path ?? null
  }
  // Read again now: it may have changed outside Claude since it was last drawn.
  if (target) await update($, files, list => list.map(f => (f.path === target ? { ...f, at: Date.now() } : f)))
  if (!target) return { text: `no Markdown edits yet this session. /${session.command} <path> opens a file.` }
  await update($, shown, () => target)
  await update($, pair, () => null)
  await fromCache($).catch(() => false) // drawn ahead: the pane opens on the page
  await $.ui.open({ id: PANE, title: 'Markdown', focus: true })
  void renderSoon($).catch(() => {})
  return { text: `${base(target)}. n/p: next/previous · b: before | after · o: browser · r: render again · t: page/text · q: close` }
}

function resetSnapshot() {
  shot.taken = false
  shot.isFull = false
  shot.listed.clear()
  shot.texts.clear()
  shot.tooBig.clear()
}

// The repo's Markdown files (tracked and untracked, not ignored), or null when git can't list them.
async function listMarkdown($: EngineInterface): Promise<string[] | null> {
  if (!session.cwd) return null
  const git = await $.process
    .run(['git', 'ls-files', '-z', '--cached', '--others', '--exclude-standard', '--', '*.md', '*.mdx', '*.markdown'], { cwd: session.cwd })
    .catch(() => null)
  if (!git || git.exitCode !== 0) return null
  const root = session.cwd.replace(/\/$/, '')
  return [...new Set(git.stdout.split('\0').filter(l => l !== '' && MD_FILE.test(l)))].map(l => `${root}/${l}`)
}

async function readAll($: EngineInterface, paths: string[]): Promise<(string | null)[]> {
  const out: (string | null)[] = []
  for (let i = 0; i < paths.length; i += 20) {
    const batch = await Promise.all(paths.slice(i, i + 20).map(p => $.fs.read(p).then(t => (typeof t === 'string' ? t : null)).catch(() => null)))
    out.push(...batch)
  }
  return out
}

async function takeSnapshot($: EngineInterface) {
  const all = await listMarkdown($)
  if (all === null) return // not a git repo, or git failed: stay off for this turn
  const paths = all.slice(0, SNAPSHOT_FILES)
  shot.isFull = all.length > SNAPSHOT_FILES
  const texts = await readAll($, paths)
  paths.forEach((p, i) => {
    shot.listed.add(p)
    const text = texts[i]
    if (typeof text === 'string' && text.length <= BEFORE_MAX) shot.texts.set(p, text)
    else shot.tooBig.add(p)
  })
  shot.taken = true
}

async function compareSnapshot($: EngineInterface) {
  const all = await listMarkdown($)
  if (all === null) return
  // A file is new only if the listing wasn't cut off; otherwise files that slid into the window would look new.
  const paths = all.filter(p => !turnBefore.has(p) && !shot.tooBig.has(p) && (shot.listed.has(p) || !shot.isFull)).slice(0, SNAPSHOT_FILES)
  const nows = await readAll($, paths)
  for (let i = 0; i < paths.length; i++) {
    const path = paths[i]
    const now = nows[i]
    if (now === null) continue
    const was = shot.texts.get(path)
    if (was === undefined) await changed($, path, null) // new file this turn
    else if (was !== now) await changed($, path, was)
  }
}

// A Markdown file changed: remember its text before and which blocks, redraw or say so.

async function changed($: EngineInterface, path: string, before: string | null) {
  const after = await $.fs.read(path).catch(() => null)
  if (typeof after !== 'string') return
  if (!turnBefore.has(path)) turnBefore.set(path, before)
  const first = turnBefore.get(path) ?? null // several edits in a turn compare with the turn's start
  const marks = changedChunks(first, after)
  const entry: MdFile = first === null || first.length > BEFORE_MAX ? { path, at: Date.now(), marks } : { path, at: Date.now(), marks, before: first }
  await update($, files, list =>
    [entry, ...list.filter(f => f.path !== path)].slice(0, MAX_FILES).map((f, i) => {
      if (i < BEFORE_FILES || f.before === undefined) return f
      const { before: _drop, ...rest } = f
      return rest
    }),
  )
  const two = await read($, pair)
  const isShown = ((await read($, shown)) === path || two?.a === path || two?.b === path) && (await paneUp($))
  if (isShown) {
    await renderSoon($)
    return
  }
  await drawAhead($, path).catch(() => {}) // quick: it queues the drawing, never waits for it
  if (toasted.has(path)) return
  toasted.add(path)
  $.ui.toast(`${base(path)} changed · /${session.command} to preview`)
}

async function step($: EngineInterface, by: number) {
  const list = await read($, files)
  if (list.length === 0) return
  const now = await read($, shown)
  const i = list.findIndex(f => f.path === now)
  const next = list[(((i + by) % list.length) + list.length) % list.length]
  if (next) await update($, shown, () => next.path)
  await update($, pair, () => null)
  await renderSoon($)
}

async function again($: EngineInterface) {
  draw.failed = ''
  session.noChrome = false
  session.chrome = ''
  session.ghDownUntil = 0
  repos.clear()
  ghFailed.clear()
  draw.force = true
  await renderSoon($) // the current picture stays up until the new one is ready
}

async function toggleView($: EngineInterface) {
  await update($, view, v => (v === 'page' ? 'text' : 'page'))
  await renderSoon($)
}

async function toggleCompare($: EngineInterface) {
  await update($, pair, () => null)
  await update($, compare, c => !c)
  await renderSoon($)
}

// One drawing at a time; a change while drawing draws once more after.
async function renderSoon($: EngineInterface) {
  if (draw.pending) {
    draw.dirty = true
    return
  }
  if (!(await plan($)) || (await read($, view)) !== 'page' || !session.canImage || session.noChrome) return
  if (!(await paneUp($))) return
  if (draw.pending) {
    draw.dirty = true // another call claimed the slot while this one checked
    return
  }
  draw.pending = true
  draw.dirty = false
  // Drawn before (ahead, or earlier this session): shown now, no Chrome.
  if (!draw.force && (await fromCache($).catch(() => false))) {
    draw.pending = false
    void afterDraw($).catch(() => {})
    return
  }
  $.clock.after(300, () => void run($, true))
}

// Draws a file Claude changed, in the background once the turn ends, so /md opens on it drawn.
// One file waits once: edited again before it is drawn, it is drawn once, as it is then.
async function drawAhead($: EngineInterface, path: string) {
  if (!session.canImage || session.noChrome || (await read($, view)) !== 'page') return
  ahead.delete(path)
  ahead.add(path)
  for (const old of ahead) if (ahead.size > AHEAD_FILES) ahead.delete(old)
  if (!turn.isOn) await startAhead($) // mid-turn, the file may change again: wait for the end
}

async function startAhead($: EngineInterface) {
  if (ahead.size === 0 || draw.pending) return // the drawing under way picks it up when done
  draw.pending = true
  draw.dirty = false
  $.clock.after(300, () => void run($, false)) // edits close together wait for each other
}

// The one drawing at a time, for the pane or ahead: two Chromes must never share the profile.
// The pane comes first; then the newest file waiting to be drawn ahead.
async function run($: EngineInterface, forPane: boolean) {
  let isPane = forPane
  try {
    if (!isPane) isPane = await paneNeeds($)
    if (isPane) await renderFile($)
    else {
      const path = turn.isOn ? undefined : [...ahead].pop() // a new turn began: wait for its end
      if (path !== undefined) {
        ahead.delete(path)
        await renderAhead($, path)
      }
    }
  } catch {
    if (isPane) {
      draw.failed = draw.drawing // no retry loop: r tries again
      await update($, note, () => 'Could not draw the page. Showing text; r tries again.').catch(() => {})
    }
  } finally {
    draw.pending = false
    void afterDraw($).catch(() => {})
  }
}

// After a drawing: the pane again if it went stale meanwhile, else the next file to draw ahead.
async function afterDraw($: EngineInterface) {
  if (draw.dirty) await drawAgainIfStale($)
  if (draw.pending || ahead.size === 0 || turn.isOn) return
  draw.pending = true
  draw.dirty = false
  void run($, false)
}

// Whether the open pane shows something other than what it should.
async function paneNeeds($: EngineInterface) {
  const p = await plan($)
  if (!p || (await read($, view)) !== 'page' || !session.canImage || session.noChrome || !(await paneUp($))) return false
  const f = await read($, frame)
  const isStale = (f === null || f.key !== p.key || f.columns !== draw.columns) && draw.failed !== `${p.key}@${draw.columns}`
  return draw.force || isStale
}

// After a drawing: once more only if what is on screen is no longer what to show.
async function drawAgainIfStale($: EngineInterface) {
  const p = await plan($)
  const f = await read($, frame)
  const isStale = p !== null && (f === null || f.key !== p.key || f.columns !== draw.columns) && draw.failed !== `${p.key}@${draw.columns}`
  if (draw.force || isStale) await renderSoon($)
}

// GitHub's own renderer, through the person's gh; null when it cannot be used.
async function github($: EngineInterface, md: string, dir: string): Promise<string | null> {
  if ((await $.clock.now()) < session.ghDownUntil) return null
  if (new TextEncoder().encode(md).length > GH_MAX_BYTES) return null // too large for the API: built-in, no penalty
  const repo = await repoOf($, dir)
  if (!repo) return null // not in a GitHub repo: the Markdown stays on this machine
  const r = await $.process
    .run(['gh', 'api', '-X', 'POST', '/markdown', '--input', '-'], { stdin: JSON.stringify({ text: md, mode: 'markdown', context: repo }), timeoutMs: GH_TIMEOUT_MS })
    .catch(() => null)
  if (!r || r.exitCode !== 0 || !r.stdout.trim()) {
    session.ghDownUntil = (await $.clock.now()) + 60_000 // offline or signed out: built-in for a minute
    ghFailed.add(repo)
    return null
  }
  ghFailed.delete(repo)
  return r.stdout
}

// A folder's GitHub repo, asked of git once (r asks again).
async function repoOf($: EngineInterface, dir: string): Promise<string | null> {
  if (repos.has(dir)) return repos.get(dir) ?? null
  const remotes = await $.process.run(['git', '-C', dir, 'remote', '-v'], { timeoutMs: 5000 }).catch(() => null)
  const repo = remotes && remotes.exitCode === 0 ? githubRepo(remotes.stdout) : null
  if (remotes) repos.set(dir, repo) // a git that could not run is asked again next time
  return repo
}

// The renderer html() would use now, without asking GitHub. A repo whose last GitHub
// render failed counts as built-in until one works (or r), so kept drawings stay found.
async function renderer($: EngineInterface, sides: Loaded[]): Promise<'GitHub' | 'built-in'> {
  if ((await $.clock.now()) < session.ghDownUntil) return 'built-in'
  for (const s of sides) {
    if (new TextEncoder().encode(withMarks(s.text, s.marks)).length > GH_MAX_BYTES) return 'built-in'
    const repo = await repoOf($, folder(s.path))
    if (!repo || ghFailed.has(repo)) return 'built-in'
  }
  return 'GitHub'
}

// What a drawing shows: the files, their texts and marks, single or compare, the width, the renderer.
async function cacheKey(p: Plan, sides: Loaded[], columns: number, via: string) {
  const what = JSON.stringify([p.key.slice(0, p.key.indexOf(':')), p.title, sides.map(s => [s.label ?? '', s.path, s.text, s.marks]), columns, via])
  const sum = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(what))
  return Array.from(new Uint8Array(sum), b => b.toString(16).padStart(2, '0')).join('')
}

// A kept drawing, now the most recently shown.
function cached(key: string) {
  const d = cache.get(key)
  if (d) {
    cache.delete(key)
    cache.set(key, d)
  }
  return d
}

// A folder for a new drawing: one no kept drawing uses and not the one on screen.
function freeSlot(onScreen: string) {
  const used = new Set([...cache.values()].map(d => d.slot))
  let slot = 0
  while (used.has(slot) || onScreen.includes(`/frame-${slot}/`)) slot++
  return slot
}

function keep(key: string, d: Drawn, onScreen: string) {
  cache.delete(key)
  cache.set(key, d)
  for (const [k, old] of cache) {
    if (cache.size <= CACHE_SIZE) break
    if (!onScreen.includes(`/frame-${old.slot}/`)) cache.delete(k) // its folder is reused later
  }
}

// Draws a plan to PNG parts, or hands back the drawing kept for the same content.
// null when Chrome could not draw it.
async function drawPage($: EngineInterface, chrome: string, p: Plan, loaded: Loaded[], columns: number, force: boolean): Promise<Drawn | null> {
  const want = await renderer($, loaded)
  const hit = force ? undefined : cached(await cacheKey(p, loaded, columns, want))
  if (hit) return hit
  const { sides, via } = await html($, loaded)
  const root = await tmpRoot($)
  const f = await read($, frame)
  const onScreen = f?.parts[0]?.file ?? ''
  // Never the folder on screen: the script empties its folder first.
  const slot = freeSlot(onScreen)
  const pagePath = `${root}/page-${slot}.html`
  const out = `${root}/frame-${slot}`
  const width = columns * CELL_PX
  await $.fs.write(pagePath, page(sides, { title: p.title, width, stacked: columns < SIDE_BY_SIDE_COLUMNS }))
  const r = await $.process.run(['sh', '-c', SCRIPT, 'md-preview', chrome, fileUrl(pagePath), out, `${root}/chrome`, String(width), '2'], { timeoutMs: 120_000 })
  const m = r.stdout.match(/(\d+) (\d+)/)
  if (r.exitCode !== 0 || !m) return null
  const rows = Number(m[1])
  const parts = Array.from({ length: Number(m[2]) }, (_, k) => ({ file: `${out}/part-${k}.png`, rows: Math.min(PART_ROWS, rows - k * PART_ROWS) }))
  draw.n = Math.max(draw.n, f?.n ?? -1) + 1 // a new picture in a folder: a new generation
  const d: Drawn = { slot, columns, parts, n: draw.n, via }
  keep(await cacheKey(p, loaded, columns, via), d, onScreen) // kept by the renderer it got
  return d
}

// Shows the kept drawing of what the pane should show, when there is one; no Chrome.
async function fromCache($: EngineInterface) {
  if ((await read($, view)) !== 'page' || !session.canImage || session.noChrome) return false
  const p = await plan($)
  if (!p) return false
  const columns = draw.columns
  const loaded = await load($, p)
  if (loaded.length === 0) return false
  const d = cached(await cacheKey(p, loaded, columns, await renderer($, loaded)))
  if (!d) return false
  await update($, note, () => '')
  await update($, frame, () => ({ key: p.key, columns, parts: d.parts, n: d.n, via: d.via }))
  return true
}

// A file drawn ahead, as /md would show it, at the pane's last width; errors stay quiet.
async function renderAhead($: EngineInterface, path: string) {
  if ((await read($, view)) !== 'page' || !session.canImage || session.noChrome) return
  const chrome = await findChrome($)
  if (!chrome) return // the pane says so when it opens
  const p = planFor(await read($, files), path, null, await read($, compare))
  if (!p) return
  const loaded = await load($, p)
  if (loaded.length === 0) return
  await drawPage($, chrome, p, loaded, draw.columns, false)
}

// Each side's HTML, from GitHub where it can.
async function html($: EngineInterface, sides: Loaded[]): Promise<{ sides: Side[]; via: 'GitHub' | 'built-in' }> {
  const mds = sides.map(s => withMarks(s.text, s.marks))
  const fromGithub: string[] = []
  for (const [k, md] of mds.entries()) {
    const h1 = await github($, md, folder((sides[k] as Loaded).path))
    if (h1 === null) break // one side cannot: all sides use the built-in renderer, so they match
    fromGithub.push(h1)
  }
  const isGithub = fromGithub.length === sides.length
  const out = sides.map((s, k) => ({ label: s.label, dir: folder(s.path), html: isGithub ? (fromGithub[k] as string) : toHtml(parse(mds[k] as string)) }))
  return { sides: out, via: isGithub ? 'GitHub' : 'built-in' }
}

async function tmpRoot($: EngineInterface) {
  const tmp = ((await $.env.get('TMPDIR').catch(() => undefined)) ?? '/tmp').replace(/\/$/, '')
  return `${tmp}/md-preview`
}

async function renderFile($: EngineInterface) {
  const p = await plan($)
  if (!p) return
  const columns = draw.columns
  const key = `${p.key}@${columns}`
  draw.drawing = key
  const force = draw.force // r: draw it again, kept drawing or not
  draw.force = false
  const chrome = await findChrome($)
  if (!chrome) {
    session.noChrome = true
    await update($, note, () => 'The rendered view needs Google Chrome (or Chromium). Showing text.')
    return
  }
  const loaded = await load($, p)
  if (loaded.length === 0) {
    draw.failed = key
    await update($, note, () => `Cannot read ${p.title}. r tries again.`)
    return
  }
  const d = await drawPage($, chrome, p, loaded, columns, force)
  if (!d) {
    draw.failed = key
    await update($, note, () => 'Chrome could not draw the page. Showing text; r tries again.')
    return
  }
  await update($, note, () => '')
  await update($, frame, () => ({ key: p.key, columns, parts: d.parts, n: d.n, via: d.via }))
}

async function findChrome($: EngineInterface) {
  if (session.chrome) return session.chrome
  for (const c of CHROMES) {
    if (await $.fs.exists(c).catch(() => false)) {
      session.chrome = c
      return c
    }
  }
  return ''
}

// The same page, full size in the person's own browser: self-contained HTML in a temp file.
// Its text has no name in front: a command reply gets one from Claude Code, the Browser button's toast adds its own.
async function openInBrowser($: EngineInterface): Promise<string> {
  if (!(await read($, shown)) && !(await read($, pair))) {
    const latest = (await read($, files))[0]?.path
    if (latest) await update($, shown, () => latest)
  }
  const p = await plan($)
  if (!p) return `nothing to open yet. /${session.command} <path> picks a file.`
  const loaded = await load($, p)
  if (loaded.length === 0) return `cannot read ${p.title}`
  const { sides } = await html($, loaded)
  const file = `${await tmpRoot($)}/open-${draw.opened++ % 5}.html` // five in turn, so they do not pile up
  await $.fs.write(file, page(sides, { title: p.title, width: 0 }))
  const opener = (await $.fs.exists('/usr/bin/open').catch(() => false)) ? 'open' : 'xdg-open'
  const r = await $.process.run([opener, file], { timeoutMs: 10_000 }).catch(() => null)
  return r && r.exitCode === 0 ? `opened ${p.title} in the browser` : `could not open the browser. The page is at ${file}`
}

files.hooks/md.ts:
// A small Markdown reader: blocks, HTML for the page, styled lines for the text view,
// and which top-level blocks the last edit changed.

// A paragraph made of this word alone marks the block after it as changed.
export const MARK = 'MDPREVIEWCHANGEDBLOCK'

type Item = { task?: boolean; blocks: Block[] }
export type Block =
  | { t: 'h'; level: number; text: string }
  | { t: 'p'; text: string }
  | { t: 'code'; lang: string; text: string }
  | { t: 'quote'; blocks: Block[] }
  | { t: 'list'; ordered: boolean; start: number; items: Item[] }
  | { t: 'table'; align: string[]; head: string[]; rows: string[][] }
  | { t: 'hr' }
  | { t: 'html'; text: string }
  | { t: 'mark' }

const FENCE = /^ {0,3}(`{3,}|~{3,})\s*([^`\s]*)/
const HEADING = /^ {0,3}(#{1,6})(?:[ \t]+(.*?))?(?:[ \t]+#+)?[ \t]*$/
const HR = /^ {0,3}([-*_])(?:[ \t]*\1){2,}[ \t]*$/
const QUOTE = /^ {0,3}> ?/
const ITEM = /^( {0,3})([-*+]|\d{1,9}[.)])([ \t]+|$)(.*)$/
const BLOCK_TAGS = 'address|article|aside|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|h[1-6]|head|header|hr|html|iframe|legend|li|link|main|menu|nav|ol|optgroup|option|p|picture|pre|script|section|source|style|summary|table|tbody|td|textarea|tfoot|th|thead|title|tr|ul|video|audio|img|a'
const HTML_START = new RegExp(`^ {0,3}(?:<!--|<\\/?(?:${BLOCK_TAGS})(?:[\\s/>]|$))`, 'i')
const DELIM = /^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)*\|?\s*$/

const isBlank = (l: string) => l.trim() === ''
const indentOf = (l: string) => (l.match(/^ */)?.[0].length ?? 0)

function startsBlock(l: string) {
  return FENCE.test(l) || HEADING.test(l) || HR.test(l) || QUOTE.test(l) || ITEM.test(l) || HTML_START.test(l)
}

function cells(row: string) {
  let r = row.trim()
  if (r.startsWith('|')) r = r.slice(1)
  if (r.endsWith('|') && !r.endsWith('\\|')) r = r.slice(0, -1)
  return r.split(/(?<!\\)\|/).map(c => c.trim().replace(/\\\|/g, '|'))
}

// Reference definitions ([id]: url), used by [text][id] and [id][] links.
let refs = new Map<string, string>()
const DEF = /^ {0,3}\[([^\]]+)\]:[ \t]*<?([^\s>]+)>?(?:[ \t]+["'(].*["')])?[ \t]*$/

export function parse(md: string): Block[] {
  const lines = md
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(l => l.replace(/^\t+/, t => '    '.repeat(t.length)))
  refs = new Map()
  let fence = ''
  const kept = lines.filter(l => {
    const f = l.match(FENCE)
    if (fence) {
      if (new RegExp(`^ {0,3}${fence[0] === '`' ? '`' : '~'}{${fence.length},}\\s*$`).test(l)) fence = ''
      return true
    }
    if (f) fence = f[1] as string
    const d = !fence && l.match(DEF)
    if (d) refs.set((d[1] as string).toLowerCase(), d[2] as string)
    return !d
  })
  return blocks(kept)
}

function blocks(lines: string[]): Block[] {
  const out: Block[] = []
  let i = 0
  while (i < lines.length) {
    const l = lines[i] as string
    if (isBlank(l)) {
      i++
      continue
    }
    if (indentOf(l) >= 4) {
      const body: string[] = []
      while (i < lines.length && (indentOf(lines[i] as string) >= 4 || isBlank(lines[i] as string))) {
        body.push((lines[i] as string).slice(4))
        i++
      }
      while (body.length && isBlank(body[body.length - 1] as string)) body.pop()
      out.push({ t: 'code', lang: '', text: body.join('\n') })
      continue
    }
    const fence = l.match(FENCE)
    if (fence) {
      const mark = fence[1] as string
      const body: string[] = []
      const pad = indentOf(l)
      i++
      while (i < lines.length && !new RegExp(`^ {0,3}${mark[0] === '`' ? '`' : '~'}{${mark.length},}\\s*$`).test(lines[i] as string)) {
        body.push((lines[i] as string).replace(new RegExp(`^ {0,${pad}}`), ''))
        i++
      }
      i++
      out.push({ t: 'code', lang: fence[2] ?? '', text: body.join('\n') })
      continue
    }
    const heading = l.match(HEADING)
    if (heading) {
      out.push({ t: 'h', level: (heading[1] as string).length, text: heading[2] ?? '' })
      i++
      continue
    }
    if (HR.test(l)) {
      out.push({ t: 'hr' })
      i++
      continue
    }
    if (QUOTE.test(l)) {
      const body: string[] = []
      while (i < lines.length && !isBlank(lines[i] as string) && (QUOTE.test(lines[i] as string) || !startsBlock(lines[i] as string))) {
        body.push((lines[i] as string).replace(QUOTE, ''))
        i++
      }
      out.push({ t: 'quote', blocks: blocks(body) })
      continue
    }
    const item = l.match(ITEM)
    if (item) {
      const r = list(lines, i)
      out.push(r.block)
      i = r.next
      continue
    }
    if (l.includes('|') && i + 1 < lines.length && DELIM.test(lines[i + 1] as string) && (lines[i + 1] as string).includes('-') && cells(lines[i + 1] as string).length === cells(l).length) {
      const head = cells(l)
      const align = cells(lines[i + 1] as string).map(c => (c.startsWith(':') && c.endsWith(':') ? 'center' : c.endsWith(':') ? 'right' : c.startsWith(':') ? 'left' : ''))
      const rows: string[][] = []
      i += 2
      while (i < lines.length && !isBlank(lines[i] as string) && (lines[i] as string).includes('|')) {
        rows.push(cells(lines[i] as string))
        i++
      }
      out.push({ t: 'table', align, head, rows })
      continue
    }
    if (HTML_START.test(l)) {
      const body: string[] = []
      if (/^ {0,3}<!--/.test(l)) {
        while (i < lines.length) {
          body.push(lines[i] as string)
          i++
          if ((body[body.length - 1] as string).includes('-->')) break
        }
        out.push({ t: 'html', text: body.join('\n') })
        continue
      }
      while (i < lines.length && !isBlank(lines[i] as string)) {
        body.push(lines[i] as string)
        i++
      }
      out.push({ t: 'html', text: body.join('\n') })
      continue
    }
    // A paragraph, or a setext heading when a line of = or - closes it.
    const body: string[] = [l]
    i++
    let level = 0
    while (i < lines.length && !isBlank(lines[i] as string)) {
      const n = lines[i] as string
      if (/^ {0,3}=+\s*$/.test(n)) level = 1
      else if (/^ {0,3}-+\s*$/.test(n)) level = 2
      if (level) {
        i++
        break
      }
      if (startsBlock(n)) break
      body.push(n)
      i++
    }
    const text = body.map(b => b.replace(/^ {0,3}/, '')).join('\n')
    if (level) out.push({ t: 'h', level, text: text.trim() })
    else if (text.trim() === MARK) out.push({ t: 'mark' })
    else out.push({ t: 'p', text })
  }
  return out
}

function list(lines: string[], from: number): { block: Block; next: number } {
  const first = (lines[from] as string).match(ITEM) as RegExpMatchArray
  const ordered = /\d/.test(first[2] as string)
  const start = ordered ? parseInt(first[2] as string, 10) : 1
  const base = (first[1] as string).length
  const items: Item[] = []
  let i = from
  while (i < lines.length) {
    const m = (lines[i] as string).match(ITEM)
    if (!m || (m[1] as string).length > base + 1 || /\d/.test(m[2] as string) !== ordered) break
    const content = (m[1] as string).length + (m[2] as string).length + Math.min(4, Math.max(1, (m[3] as string).length))
    const body: string[] = [m[4] ?? '']
    i++
    while (i < lines.length) {
      const n = lines[i] as string
      if (isBlank(n)) {
        // A blank line ends the item unless what follows is indented into it.
        let j = i + 1
        while (j < lines.length && isBlank(lines[j] as string)) j++
        if (j < lines.length && indentOf(lines[j] as string) >= content) {
          for (; i < j; i++) body.push('')
          continue
        }
        break
      }
      if (indentOf(n) >= content) {
        body.push(n.slice(content))
        i++
        continue
      }
      if (ITEM.test(n) || startsBlock(n)) break
      body.push(n.trim()) // a lazy continuation of the paragraph
      i++
    }
    let task: boolean | undefined
    const t = (body[0] ?? '').match(/^\[([ xX])\][ \t]+/)
    if (t) {
      task = t[1] !== ' '
      body[0] = (body[0] ?? '').slice(t[0].length)
    }
    items.push({ task, blocks: blocks(body) })
    // A blank line between items keeps the list going.
    let j = i
    while (j < lines.length && isBlank(lines[j] as string)) j++
    const nm = j < lines.length ? (lines[j] as string).match(ITEM) : null
    if (j > i && nm && (nm[1] as string).length <= base + 1 && /\d/.test(nm[2] as string) === ordered) i = j
  }
  return { block: { t: 'list', ordered, start, items }, next: i }
}

// --- HTML ---

export function esc(s: string) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/<[^>]+>/g, '')
    .replace(/[^\p{L}\p{N}\s_-]/gu, '')
    .trim()
    .replace(/\s/g, '-')

export function inline(text: string): string {
  const keep: string[] = []
  const hold = (html: string) => `\u0000${keep.push(html) - 1}\u0000`
  let s = text
  s = s.replace(/(`+)([\s\S]*?[^`])\1(?!`)/g, (_m, _t, code: string) => hold(`<code>${esc(code.replace(/\n/g, ' ').trim())}</code>`))
  s = s.replace(/\\([\\`*_{}[\]()#+\-.!|~<>])/g, (_m, c: string) => hold(esc(c)))
  s = s.replace(/&(#\d+|#x[\da-f]+|[a-z][a-z\d]*);/gi, m => hold(m)) // an entity stays one
  s = s.replace(/<(https?:\/\/[^\s>]+)>/g, (_m, url: string) => hold(`<a href="${esc(url)}">${esc(url)}</a>`))
  s = s.replace(/<\/?[a-zA-Z][\w-]*(?:\s[^<>]*)?\/?>|<!--[\s\S]*?-->/g, tag => hold(tag)) // inline HTML passes through
  s = esc(s)
  const URL_ = '((?:[^()\\s]|\\([^()\\s]*\\))*)' // one level of balanced parentheses
  const TITLE = '(?:\\s+&quot;([^&]*)&quot;)?'
  const ref = (label: string, id: string) => refs.get((id || label).replace(/\u0000\d+\u0000/g, '').toLowerCase())
  s = s.replace(new RegExp(`!\\[([^\\]]*)\\]\\(\\s*${URL_}${TITLE}\\s*\\)`, 'g'), (_m, alt: string, src: string, title?: string) => hold(`<img src="${safeUrl(src)}" alt="${alt}"${title ? ` title="${title}"` : ''}>`))
  s = s.replace(new RegExp(`\\[((?:[^\\]\\\\]|\\\\.)*)\\]\\(\\s*${URL_}${TITLE}\\s*\\)`, 'g'), (_m, label: string, href: string, title?: string) => hold(`<a href="${safeUrl(href)}"${title ? ` title="${title}"` : ''}>${emphasis(label)}</a>`))
  s = s.replace(/!\[([^\]]*)\]\[([^\]]*)\]/g, (m, alt: string, id: string) => {
    const url = ref(alt, id)
    return url ? hold(`<img src="${safeUrl(esc(url))}" alt="${alt}">`) : m
  })
  s = s.replace(/\[((?:[^\]\\]|\\.)*)\]\[([^\]]*)\]/g, (m, label: string, id: string) => {
    const url = ref(label, id)
    return url ? hold(`<a href="${safeUrl(esc(url))}">${emphasis(label)}</a>`) : m
  })
  s = s.replace(/(^|[\s(])(https?:\/\/[^\s<]*[^\s<.,;:!?)'"\u0000])/g, (_m, pre: string, url: string) => `${pre}${hold(`<a href="${url}">${url}</a>`)}`)
  s = emphasis(s)
  s = s.replace(/(?: {2,}|\\)\n/g, '<br>\n')
  return s.replace(/\u0000(\d+)\u0000/g, (_m, n: string) => keep[Number(n)] ?? '').replace(/\u0000(\d+)\u0000/g, (_m, n: string) => keep[Number(n)] ?? '')
}

// Only web, mail, relative and in-page links; never javascript: and the like.
function safeUrl(url: string) {
  return /^\s*(?:javascript|vbscript|data|file):/i.test(url.replace(/&#?\w+;|[\u0000-\u001f]/g, '')) ? '#' : url
}

/** Drops what can run: script-like elements and on* handlers, javascript: URLs. */
export function sanitize(html: string) {
  return html
    .replace(/<(script|style|iframe|object|embed|frame|frameset|applet|base|meta|link|form)\b[\s\S]*?(?:<\/\1\s*>|$)/gi, '')
    .replace(/<\/?(script|style|iframe|object|embed|frame|frameset|applet|base|meta|link|form)\b[^>]*>/gi, '')
    .replace(/<[a-z][^>]*>/gi, tag =>
      tag
        .replace(/\s+on[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, '')
        .replace(/\b(href|src|action|formaction|srcset)\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, (m, attr: string, v: string) => (safeUrl(v.replace(/^["']|["']$/g, '')) === '#' ? `${attr}="#"` : m)),
    )
}

function emphasis(s: string) {
  return s
    .replace(/(\*\*|__)(?=\S)([\s\S]*?\S)\1/g, '<strong>$2</strong>')
    .replace(/\*(?=\S)([\s\S]*?\S)\*/g, '<em>$1</em>')
    .replace(/(^|[^\w])_(?=\S)([\s\S]*?\S)_(?!\w)/g, '$1<em>$2</em>')
    .replace(/~~(?=\S)([\s\S]*?\S)~~/g, '<del>$1</del>')
}

// The built-in renderer's HTML: the Markdown's own HTML passes through, made safe.
export function toHtml(list: Block[]): string {
  return sanitize(list.map(blockHtml).join('\n'))
}

function blockHtml(b: Block): string {
  switch (b.t) {
    case 'h': {
      const body = inline(b.text)
      return `<h${b.level} id="${slug(b.text)}">${body}</h${b.level}>`
    }
    case 'p':
      return `<p>${inline(b.text)}</p>`
    case 'code':
      return `<pre><code${b.lang ? ` class="language-${esc(b.lang)}"` : ''}>${esc(b.text)}</code></pre>`
    case 'quote':
      return `<blockquote>\n${toHtml(b.blocks)}\n</blockquote>`
    case 'list': {
      const tag = b.ordered ? 'ol' : 'ul'
      const hasTask = b.items.some(it => it.task !== undefined)
      const items = b.items.map(it => {
        // A one-paragraph item is drawn tight, as GitHub does.
        const inner = it.blocks.length >= 1 && it.blocks[0]?.t === 'p' ? [inline(it.blocks[0].text), ...it.blocks.slice(1).map(blockHtml)].join('\n') : toHtml(it.blocks)
        const box = it.task === undefined ? '' : `<input type="checkbox" class="task-list-item-checkbox" disabled${it.task ? ' checked' : ''}> `
        return `<li${it.task !== undefined ? ' class="task-list-item"' : ''}>${box}${inner}</li>`
      })
      const start = b.ordered && b.start !== 1 ? ` start="${b.start}"` : ''
      return `<${tag}${start}${hasTask ? ' class="contains-task-list"' : ''}>\n${items.join('\n')}\n</${tag}>`
    }
    case 'table': {
      const al = (i: number) => (b.align[i] ? ` align="${b.align[i]}"` : '')
      const head = b.head.map((c, i) => `<th${al(i)}>${inline(c)}</th>`).join('')
      const rows = b.rows.map(r => `<tr>${b.head.map((_c, i) => `<td${al(i)}>${inline(r[i] ?? '')}</td>`).join('')}</tr>`).join('\n')
      return `<table>\n<thead><tr>${head}</tr></thead>\n<tbody>\n${rows}\n</tbody>\n</table>`
    }
    case 'hr':
      return '<hr>'
    case 'html':
      return b.text
    case 'mark':
      return '<div class="md-mark"></div>'
  }
}

// --- What changed ---

// Top-level chunks: runs of lines split by blank lines outside code fences.
export function chunks(md: string): string[] {
  const out: string[] = []
  let cur: string[] = []
  let fence = ''
  for (const l of md.replace(/\r\n?/g, '\n').split('\n')) {
    const f = l.match(FENCE)
    if (fence) {
      cur.push(l)
      if (new RegExp(`^ {0,3}${fence[0] === '`' ? '`' : '~'}{${fence.length},}\\s*$`).test(l)) fence = ''
      continue
    }
    if (f) fence = f[1] as string
    if (isBlank(l) && !fence) {
      if (cur.length) out.push(cur.join('\n'))
      cur = []
      continue
    }
    cur.push(l)
  }
  if (cur.length) out.push(cur.join('\n'))
  return out
}

// The chunks of `after` that `before` did not have; none for a new file.
export function changedChunks(before: string | null, after: string): number[] {
  if (before === null || before.trim() === '') return []
  const old = new Map<string, number>()
  for (const c of chunks(before)) old.set(c.trim(), (old.get(c.trim()) ?? 0) + 1)
  const out: number[] = []
  chunks(after).forEach((c, i) => {
    const k = c.trim()
    const n = old.get(k) ?? 0
    if (n > 0) old.set(k, n - 1)
    else out.push(i)
  })
  return out
}

// The Markdown again, a MARK paragraph before each changed chunk that starts a block.
export function withMarks(md: string, marks: readonly number[]): string {
  if (marks.length === 0) return md
  const list = chunks(md)
  const at = new Set<number>()
  let start = -1 // the first chunk of the list run this chunk belongs to
  list.forEach((c, i) => {
    const isListish = ITEM.test(c) || indentOf(c) > 0
    start = isListish && i > 0 && start >= 0 && (ITEM.test(list[i - 1] as string) || indentOf(list[i - 1] as string) > 0) ? start : i
    if (marks.includes(i)) at.add(isListish ? start : i)
  })
  return list.map((c, i) => (at.has(i) && indentOf(c) < 4 ? `${MARK}\n\n${c}` : c)).join('\n\n')
}

// --- Text view ---

export type Seg = { text: string; bold?: boolean; italic?: boolean; dim?: boolean; color?: string; underline?: boolean; strike?: boolean }
export type Line = { prefix: string; segs: Seg[]; mark?: boolean }

const INLINE = /(`+)([\s\S]*?[^`])\1(?!`)|!\[([^\]]*)\]\([^)]*\)|\[((?:[^\]\\]|\\.)*)\]\(\s*([^)\s]*)[^)]*\)|<(https?:\/\/[^>\s]+)>|(\*\*|__)(?=\S)([\s\S]*?\S)\7|\*(?=\S)([^*]*?\S)\*|(?<![\w])_(?=\S)([^_]*?\S)_(?!\w)|~~([\s\S]*?)~~|<\/?[a-zA-Z][^<>]*>|<!--[\s\S]*?-->/g

export function segments(text: string): Seg[] {
  const out: Seg[] = []
  const plain = (t: string) => t && out.push({ text: t.replace(/\\([\\`*_{}[\]()#+\-.!|~<>])/g, '$1').replace(/\s*\n\s*/g, ' ') })
  let at = 0
  for (const m of text.matchAll(INLINE)) {
    plain(text.slice(at, m.index))
    at = (m.index ?? 0) + m[0].length
    if (m[2] !== undefined) out.push({ text: m[2].trim(), color: 'cyan' })
    else if (m[3] !== undefined) out.push({ text: `[image: ${m[3] || 'untitled'}]`, dim: true })
    else if (m[4] !== undefined) {
      out.push({ text: m[4].replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/[*_`]/g, ''), color: 'blue', underline: true })
      if (m[5] && !m[5].startsWith('#')) out.push({ text: ` (${m[5]})`, dim: true })
    } else if (m[6] !== undefined) out.push({ text: m[6], color: 'blue', underline: true })
    else if (m[8] !== undefined) out.push({ text: m[8], bold: true })
    else if (m[9] !== undefined) out.push({ text: m[9], italic: true })
    else if (m[10] !== undefined) out.push({ text: m[10], italic: true })
    else if (m[11] !== undefined) out.push({ text: m[11], strike: true })
    // an HTML tag or comment: dropped, its text stays
  }
  plain(text.slice(at))
  return out
}

const plainText = (segs: Seg[]) => segs.map(s => s.text).join('')

export function toLines(list: Block[], width = 80): Line[] {
  const out: Line[] = []
  let marked = false
  const push = (ls: Line[]) => {
    for (const l of ls) out.push(marked ? { ...l, mark: true } : l)
    marked = false
  }
  for (const b of list) {
    if (b.t === 'mark') {
      marked = true
      continue
    }
    if (out.length) out.push({ prefix: '', segs: [] })
    push(blockLines(b, width))
  }
  return out
}

function blockLines(b: Block, width: number): Line[] {
  switch (b.t) {
    case 'h': {
      const segs = segments(b.text).map(s => ({ ...s, bold: true, color: b.level <= 2 ? 'magenta' : 'cyan' }))
      const ls: Line[] = [{ prefix: '', segs }]
      if (b.level <= 2) ls.push({ prefix: '', segs: [{ text: '─'.repeat(Math.min(width, Math.max(8, plainText(segs).length))), dim: true }] })
      return ls
    }
    case 'p':
      return [{ prefix: '', segs: segments(b.text) }]
    case 'code':
      return b.text.split('\n').map(l => ({ prefix: '  │ ', segs: [{ text: l, dim: true }] }))
    case 'quote':
      return toLines(b.blocks, width - 2).map(l => ({ ...l, prefix: `▎ ${l.prefix}`, segs: l.segs.map(s => ({ ...s, dim: true })) }))
    case 'list': {
      const ls: Line[] = []
      b.items.forEach((it, n) => {
        const bullet = it.task === true ? '☑ ' : it.task === false ? '☐ ' : b.ordered ? `${b.start + n}. ` : '• '
        const pad = ' '.repeat(bullet.length)
        toLines(it.blocks, width - bullet.length)
          .filter(l => l.segs.length > 0)
          .forEach((l, k) => ls.push({ ...l, prefix: `${k === 0 ? bullet : pad}${l.prefix}` }))
      })
      return ls
    }
    case 'table': {
      const rows = [b.head, ...b.rows].map(r => b.head.map((_c, i) => plainText(segments(r[i] ?? ''))))
      const widths = b.head.map((_c, i) => Math.max(...rows.map(r => (r[i] ?? '').length)))
      const fmt = (r: string[]) => r.map((c, i) => c.padEnd(widths[i] ?? 0)).join(' │ ')
      const ls: Line[] = [{ prefix: '', segs: [{ text: fmt(rows[0] ?? []), bold: true }] }]
      ls.push({ prefix: '', segs: [{ text: widths.map(w => '─'.repeat(w)).join('─┼─'), dim: true }] })
      for (const r of rows.slice(1)) ls.push({ prefix: '', segs: [{ text: fmt(r) }] })
      return ls
    }
    case 'hr':
      return [{ prefix: '', segs: [{ text: '─'.repeat(Math.min(width, 40)), dim: true }] }]
    case 'html': {
      const alts = [...b.text.matchAll(/<img[^>]*\balt="([^"]*)"/gi)].map(m => `[image: ${m[1] || 'untitled'}]`)
      const text = b.text
        .replace(/<!--[\s\S]*?-->/g, '')
        .replace(/<[^>]+>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
      const all = [text, ...alts].filter(Boolean).join(' ')
      return all ? [{ prefix: '', segs: [{ text: all, dim: true }] }] : []
    }
    case 'mark':
      return []
  }
}

